tools.usage:
EXPORT SCRIPT    filename;
EXPORT NETLIST   filename;
EXPORT SPICENETLIST   filename;
EXPORT NETSCRIPT filename;
EXPORT PARTLIST  filename;
EXPORT PINLIST   filename;
EXPORT DIRECTORY filename;
EXPORT IMAGE     filename|CLIPBOARD [MONOCHROME|WINDOW] resolution;

tools.example:
EDIT myproject.sch;
EXPORT NETLIST myproject.net;
EXPORT PARTLIST myproject_parts.txt;
EXPORT IMAGE myproject.png 300;

EDIT myproject.sch;
EXPORT NETSCRIPT nets.scr;
EDIT otherboard.brd;
DELETE SIGNALS;
SCRIPT nets.scr;

OPEN mylib;
EXPORT SCRIPT mylib.scr;
OPEN mylib_new;
SET UNDO_LOG OFF;
SCRIPT mylib.scr;
SET UNDO_LOG ON;

DISPLAY NONE TOP PADS VIAS DIMENSION;
EXPORT IMAGE top_copper.png MONOCHROME 600;
DISPLAY LAST;
EXPORT IMAGE CLIPBOARD WINDOW 150;

CHANGE WIDTH 0.15;
CHANGE DRILL 0.3;
FANOUT DEVICE U3 OUT;
FANOUT SIGNAL GND ALTERNATE;

GRID MM 1 10 LINES ON;
LINE 0 (0 0) (100 0);
GRID LAST;

tools.usage:
GRID MIC | MM | MIL | INCH;
GRID option..;
GRID ALT ...;

tools.example:
GRID = Fine mm 0.1 lines on;
GRID = Coarse inch 0.1 dots on;
GRID fine;

tools.usage:
LABEL XREF [orientation] • •..
SET XREF_LABEL_FORMAT string;
CHANGE XREF OFF | ON

tools.example:
OPEN mylib;
EDIT SOT23.dev;
LAUNCH PACKAGE3D-GENERATOR

LAYER 101 SAMPLE;
LAYER tDocu;
LINE 0.1 (0 0) (10 0);
LAYER ?? -101;

GRID MM 1;
CHANGE LAYER DIMENSION;
LINE 0 (0 0) (160 0) (160 100) (0 100) (0 0);
GRID LAST;

tools.usage:
LOCK
LOCK *;
LOCK -*;
LOCK name;
LOCK -name;
LOCK LAYER layer_name;
LOCK LAYER -layer_name;
LOCK LAYER layer_number;
LOCK LAYER -layer_number;

tools.example:
MENU 'Grid {\
  Fine : Grid mm 0.1; |\
  Coarse : Grid mm 1;\
}' 'MyDisp : Display None Top Bottom Pads Vias;' ';';
